/** Events */
export const events = {
	settingsChangedEvent: makeEvent<SettingsChangedEvent>("settings-changed-event"),
};

/* Types */
/**
 *  The All view: open Tasks grouped (by List unless changed), the Inbox first. Empty groups are
 *  left out.
 */
export type AllView = {
	/**  How it is grouped (a Preference). */
	group_by: GroupBy,
	/**  Groups in order. */
	groups: TaskGroup[],
};

/**  Error returned from commands: `{code, message, details}`. */
export type AppError = {
	/**  Category for UI branching. */
	code: ErrorCode,
	/**  Short, user-presentable summary. */
	message: string,
	/**  Technical detail for "copy details"; never shown by default. */
	details: string | null,
};

/**  Static facts about this running app. */
export type AppInfo = {
	version: string,
	environment: Environment,
	data_dir: string,
	log_dir: string,
	/**  First name from the OS account, for the greeting when no display name is set. */
	os_first_name: string,
};

/**
 *  A note left on a Task. It belongs to the Task row it was written on: for a repeating Task, the
 *  current occurrence (completing moves it to the done copy).
 */
export type Comment = {
	/**  `UUIDv7`. */
	id: string,
	/**  The Task it is on. */
	task_id: string,
	/**  Text with inline Markdown marks (line breaks allowed), up to 5000 characters. */
	body: string,
	/**  Whether it was changed after it was written. */
	edited: boolean,
	/**  When it was written: UTC milliseconds. */
	created_at: number,
	/**  When it was last edited: UTC milliseconds. */
	updated_at: number,
};

/**  What ticking a Task did. */
export type Completion = {
	/**  The Task: done, or for a repeating one still open on its next date. */
	task: Task,
	/**
	 *  For a repeating Task, the done copy that records this occurrence. Reopening it (the
	 *  latest occurrence) is the Undo.
	 */
	occurrence: Task | null,
};

/**  The number of open Tasks due on one date. */
export type DayCount = {
	/**  `YYYY-MM-DD`. */
	date: string,
	/**  Open Tasks due that day. */
	count: number,
};

/**  What happens to a deleted List's Tasks. */
export type DeleteChoice = 
/**  Delete them with the List (the default). */
{ kind: "delete_tasks" } | 
/**  Move them to the Inbox. */
{ kind: "move_to_inbox" } | 
/**  Move them to another List. */
{ kind: "move_to_list"; 
/**  The receiving List. */
list_id: string };

/**  Everything stored per device. */
export type DeviceSettings = {
	/**  Custom data folder; `None` means the platform default. */
	data_dir?: string | null,
	/**  Window geometry. */
	window?: WindowState,
	/**  Sidebar layout. */
	sidebar?: SidebarState,
	/**  `tracing` level: error, warn, info, debug or trace. */
	log_level?: string,
	/**  Spellcheck in every text editor. Per device: input methods and dictionaries differ. */
	spellcheck?: boolean,
};

/**  The Tasks done on one day of Done. */
export type DoneDay = {
	/**  The device's day, `YYYY-MM-DD`. */
	date: string,
	/**  Newest first. */
	tasks: Task[],
};

/**  What a List page does with its Done Tasks. */
export type DoneInLists = 
/**  Done today struck through at the bottom, older ones behind "Done earlier". */
"today_shown" | 
/**  All behind one fold. */
"folded" | 
/**  All shown, struck through. */
"shown" | 
/**  None. */
"hidden";

/**  One page of Done: whole days, newest first. */
export type DoneView = {
	/**  The days of this page. */
	days: DoneDay[],
	/**  Hand it back as the cursor for the next page; none when this was the last. */
	next_cursor: string | null,
};

/**  A slice of time by Due date, for grouping by Due date. */
export type DueBucket = 
/**  Before today. */
"overdue" | 
/**  Today. */
"today" | 
/**  Tomorrow. */
"tomorrow" | 
/**  The six days after tomorrow. */
"week" | 
/**  Further away. */
"later" | 
/**  No Due date. */
"no_date";

/**
 *  A Task's Due date, time and Repeat as they were, for Undo. A past date can only come back this
 *  way.
 */
export type DueChange = {
	/**  The Task. */
	id: string,
	/**  Due date, `YYYY-MM-DD`. */
	due_date: string | null,
	/**  Due time, `HH:MM`. */
	due_time: string | null,
	/**  The Repeat, which goes with the date. */
	repeat: RepeatRule | null,
};

/**  One untitled piece of writing on a Page. */
export type Entry = {
	/**  `UUIDv7`. */
	id: string,
	/**  The Page this Entry sits on, `YYYY-MM-DD`. */
	page_date: string,
	/**  Markdown text. */
	body: string,
	/**  When it was written: UTC milliseconds. Never changes. */
	written_at: number,
	/**  UTC offset in minutes where it was written. */
	written_offset_min: number,
	/**  IANA zone where it was written. */
	written_tz: string,
	/**  When it was last meaningfully edited: UTC milliseconds. */
	edited_at: number | null,
	/**  Words in the body, not counting Markdown symbols. */
	word_count: number,
	/**  Row creation time: UTC milliseconds. */
	created_at: number,
	/**  Row update time: UTC milliseconds. */
	updated_at: number,
};

/**  Which data set the app uses. Chosen by the `sandbox` cargo feature of the app crate. */
export type Environment = 
/**  The user's real data. */
"production" | 
/**  Separate, disposable data. */
"sandbox";

/**  Machine-readable failure category the UI can branch on. */
export type ErrorCode = 
/**  A value failed validation. */
"validation" | 
/**  A key is not registered. */
"unknown_key" | 
/**  The record asked for does not exist (or is deleted). */
"not_found" | 
/**  Filesystem failure. */
"io" | 
/**  Database failure. */
"database" | 
/**  Anything else; a bug or an unexpected state. */
"internal";

/**  What a view groups its Tasks by. */
export type GroupBy = 
/**  One plain group. */
"none" | 
/**  One group per Priority. */
"priority" | 
/**  One group per List, the Inbox first. */
"list" | 
/**  One group per Due date (Upcoming). */
"day" | 
/**  Overdue, Today, Tomorrow, the next days, later, and no date. */
"due";

/**  Which group of a view a Task is in: what a heading says and what a drop adopts. */
export type GroupKey = 
/**  The one group of an ungrouped view. */
{ kind: "plain" } | 
/**  Due before today, on top in Today and Upcoming. */
{ kind: "overdue" } | 
/**  One Priority, 1 to 4 (4 is "No priority"). */
{ kind: "priority"; 
/**  1 to 4. */
priority: number } | 
/**  One List; none is the Inbox. */
{ kind: "list"; 
/**  The List. */
list_id: string | null } | 
/**  One day. */
{ kind: "day"; 
/**  `YYYY-MM-DD`. */
date: string } | 
/**  A slice of time by Due date. */
{ kind: "due"; 
/**  Which. */
bucket: DueBucket } | 
/**  The Inbox's "No date, in a List". */
{ kind: "no_date_in_list" };

/**  One line of a Task's History. */
export type HistoryLine = {
	/**  When it happened: UTC milliseconds. */
	at: number,
	/**
	 *  What kind of change: `create`, `done`, `skip`, `reopen`, `wont`, `delete`, `restore`,
	 *  `list`, `date`, `time`, `repeat`, `priority`, `title` or `notes`. The UI picks an icon from it.
	 */
	kind: string,
	/**  The readable line. */
	text: string,
};

/**  One Entry found by a search. */
export type Hit = {
	/**  The Entry's id. */
	id: string,
	/**  The Page it sits on, `YYYY-MM-DD`. */
	page_date: string,
	/**  When it was written: UTC milliseconds. */
	written_at: number,
	/**  UTC offset in minutes where it was written. */
	written_offset_min: number,
	/**  IANA zone where it was written. */
	written_tz: string,
	/**  A window of its text with the matches marked. */
	snippet: Span[],
};

/**
 *  The Inbox: open Tasks that belong to no List, in groups, then the undated Tasks that sit in a
 *  List. Only the first part counts toward the badge.
 */
export type InboxView = {
	/**  How the Tasks with no List are grouped (a Preference). */
	group_by: GroupBy,
	/**  How they sort inside each group (a Preference). */
	sort: TaskSort,
	/**  Groups of Tasks with no List, then "No date, in a List" when there are such Tasks. */
	groups: TaskGroup[],
};

/**
 *  TypeScript-facing description of any JSON value. Only used for type generation: on the wire
 *  fields stay `serde_json::Value`, which specta cannot export (recursive, i64 numbers).
 */
export type JsonValue = null | boolean | number | null | string | JsonValue[] | { [key in string]: JsonValue };

/**  What a List deletion did: hand it back to `todo_list_restore` to undo it. */
export type ListDeletion = {
	/**  The deleted List. */
	list_id: string,
	/**  Tasks that were deleted with it. */
	deleted_task_ids: string[],
	/**  Tasks that were moved out of it. */
	moved_task_ids: string[],
};

/**  A List page's Done Tasks, as the Done-in-Lists Preference says to show them. */
export type ListDone = {
	/**  The Preference in force. */
	mode: DoneInLists,
	/**  Struck through at the bottom: done today, or everything with "All shown". Newest first. */
	shown: Task[],
	/**  Behind a fold: "Done earlier · N", or "Done · N" with "All folded". Newest first. */
	folded: Task[],
};

/**  A List with its Task counts. */
export type ListEntry = {
	/**  The List. */
	list: TodoList,
	/**  Open Tasks in it. */
	open_count: number,
	/**  Every Task in it, done ones too: what deleting the List has to deal with. */
	task_count: number,
};

/**  How the Lists in the sidebar are ordered. */
export type ListSort = 
/**  The drag order. */
"manual" | 
/**  Name, A to Z. */
"name_asc" | 
/**  Name, Z to A. */
"name_desc" | 
/**  Most open Tasks first. */
"most_open" | 
/**  Oldest first. */
"created";

/**  One List's page: the List, its open Tasks in groups, and its Done Tasks. */
export type ListView = {
	/**  The List, whose `group_by` and `task_sort` the groups follow. */
	list: TodoList,
	/**  Open Tasks: grouped first, sorted inside each group. */
	groups: TaskGroup[],
	/**  Done and Won't do Tasks. */
	done: ListDone,
};

/**  What the UI says "now" is on the device: every date-dependent command takes one. */
export type LocalNow = {
	/**  Today's date, `YYYY-MM-DD`. "Today" ends at midnight, like the Journal's. */
	today: string,
	/**  The time of day, `HH:MM`. */
	now: string,
	/**
	 *  Minutes the device's clock is ahead of UTC. Only needed to tell which Tasks were closed
	 *  today, because closing times are stored in UTC.
	 */
	offset_min: number,
};

/**  Everything the UI supplies to write a new Entry. */
export type NewEntry = {
	/**  The Page to put it on, `YYYY-MM-DD`. Future dates are fine. */
	page_date: string,
	/**  Markdown text. */
	text: string,
	/**  IANA zone of the writer's device. */
	written_tz: string,
	/**  UTC offset in minutes of the writer's device. */
	written_offset_min: number,
	/**  The composer session writing this Entry; groups its autosaves in the change log. */
	session_id: string,
};

/**  What a captured Task carries besides its title, List and When. */
export type NewTaskDetails = {
	/**  Markdown notes. */
	notes?: string,
	/**  1 to 4; none means 4. */
	priority: number | null,
	/**  A Repeat; it needs the clock of `when` to find its first day. */
	repeat: RepeatRule | null,
	/**  What the parser recognised, as JSON `[{word, kind, value}]`. */
	understood: string | null,
};

/**  A date and time to give a new Task, with the clock it was picked against. */
export type NewWhen = {
	/**  Due date, `YYYY-MM-DD`. */
	date: string | null,
	/**  Due time, `HH:MM`; with no date it means today if still ahead, otherwise tomorrow. */
	time: string | null,
	/**  The device's clock. */
	local: LocalNow,
};

/**  What "Move all" did: hand `previous` to `todo_tasks_restore_when` to undo it. */
export type OverdueMove = {
	/**  The date they were moved to. */
	to_date: string,
	/**  The Tasks moved, with the date and time each had. */
	previous: DueChange[],
};

/**  All Entries of one date, oldest first. */
export type Page = {
	/**  `YYYY-MM-DD`. */
	date: string,
	/**  How many Entries the Page holds. */
	entry_count: number,
	/**  Words across all its Entries, for the header summary. */
	word_count: number,
	/**  Entries by written instant, oldest first. */
	entries: Entry[],
};

/**  Which Pages a `cursor` date selects. Results are always newest first. */
export type PageDirection = 
/**  Pages strictly before the cursor (older). No cursor: the newest Pages. */
"older" | 
/**  The cursor's own Page and older ones: the feed starting AT a date. No cursor: the newest. */
"from" | 
/**  The Pages just after the cursor (newer), nearest first picked; needs a cursor. */
"newer";

/**  A word that was recognised but did not win. */
export type ParseAlternative = {
	/**  Why it lost: `conflict` (a later one of the same kind won). */
	reason: string,
} & ParseSpan;

/**  What to read, and what the user has already decided. */
export type ParseRequest = {
	/**  The typed text. */
	text: string,
	/**  Keys of words the user keeps as text. */
	ignored?: string[],
	/**  Per kind, the key of the word the user picked over the last one ("use instead"). */
	prefer?: { [key in string]: string },
	/**  Stretches already read before (Quick edit's old title): candidates inside them are dropped. */
	frozen?: TextRange[],
	/**  Today, `YYYY-MM-DD`. */
	today: string,
	/**  The time of day, `HH:MM`. */
	now: string,
	/**  `mon` or `sun`: the first day of the week, which "next week" and "next fri" count from. */
	week_start: string,
};

/**  A recognised word and what it means. */
export type ParseSpan = {
	/**  Names the word across parses: `kind:word:n` for the nth such word in the text. */
	key: string,
	/**  `date`, `time`, `repeat`, `prio` or `list`. */
	kind: string,
	/**  Where it starts in the text. */
	start: number,
	/**  Where it ends. */
	end: number,
	/**  The words as typed. */
	word: string,
	/**
	 *  The meaning: a `YYYY-MM-DD` date, an `HH:MM` time, the Repeat as JSON, a Priority number
	 *  or a List's name.
	 */
	value: string,
	/**  A List that does not exist yet and is created when the Task is added. */
	new_list: boolean,
};

/**  What the text means. */
export type Parsed = {
	/**  The words that won, first to last. */
	spans: ParseSpan[],
	/**  The words that lost. */
	alternatives: ParseAlternative[],
	/**  The words the user keeps as text, which would have been read. */
	ignored: ParseSpan[],
	/**  The Due date: a date word, or today/tomorrow for a time alone. */
	date: string | null,
	/**  The Due time. */
	time: string | null,
	/**  The Repeat. */
	repeat: RepeatRule | null,
	/**  1 to 4. */
	priority: number | null,
	/**  The List a `#Name` matched. */
	list_id: string | null,
	/**  A `#Name` that matched nothing: the List to create. */
	new_list: string | null,
};

/**
 *  Everything Quick edit can change, as the Task should be afterwards. What the box left alone is
 *  passed back as it was.
 */
export type QuickEdit = {
	/**  The title as typed. */
	title: string,
	/**  What the parser recognised in it, as JSON. */
	understood: string | null,
	/**  Due date, `YYYY-MM-DD`. */
	due_date: string | null,
	/**  Due time, `HH:MM`. */
	due_time: string | null,
	/**  The Repeat after the edit. */
	repeat: RepeatRule | null,
	/**  1 to 4. */
	priority: number,
	/**  The List, or none for the Inbox. */
	list_id: string | null,
};

/**  A Repeat as it crosses IPC and is stored in the Task's columns. */
export type RepeatRule = {
	/**  `day`, `week`, `month` or `year`. */
	freq: string,
	/**  The interval, 1 to 99. */
	every: number,
	/**
	 *  Weeks: a bitmask of the weekdays (Sunday is bit 0), none meaning the Due date's own
	 *  weekday. Months and years: the day of the month the Repeat keeps to (31 clamps to the
	 *  last day of a short month and comes back), set from the Due date.
	 */
	days: number | null,
	/**  `fixed` (from the Due date) or `after` (from the day it was done). */
	mode: string,
};

/**  The outcome of a search. */
export type SearchResults = {
	/**  Entries that match every word and phrase, newest first. */
	exact: Hit[],
	/**  Entries that match only when a word is allowed a typo; never also in `exact`. */
	similar: Hit[],
	/**  Whether `exact` was cut short at the limit. */
	truncated: boolean,
	/**  Whether `similar` was cut short at the limit. */
	similar_truncated: boolean,
};

/**  Wire form of a registered key, so the UI can render defaults and reset buttons. */
export type SettingSchema = {
	/**  Full key, `module.key`. */
	key: string,
	/**  Owning Module id. */
	module: string,
	/**  Default value. */
	default: JsonValue,
};

/**  One requested change; `key` is the full `module.key`. */
export type SettingsChange = {
	/**  Full key, `module.key`. */
	key: string,
	/**  New value. */
	value: JsonValue,
};

/**  Some Settings keys of one Module were saved. */
export type SettingsChanged = {
	/**  Owning Module id, e.g. `core`. */
	module: string,
	/**  Keys within that Module (without the module prefix). */
	keys: string[],
};

/**  Typed IPC event mirroring core's `SettingsChanged`, emitted to the webview. */
export type SettingsChangedEvent = SettingsChanged;

/**  Everything the UI needs to render Settings. */
export type SettingsSnapshot = {
	/**  Current value of every registered key (defaults filled in). */
	values: { [key in string]: JsonValue },
	/**  Registered keys with their defaults. */
	schema: SettingSchema[],
};

/**  Sidebar layout. */
export type SidebarState = {
	/**  Expanded width in pixels (200 to 360). */
	width?: number,
	/**  Collapsed to the icon rail. */
	rail?: boolean,
	/**
	 *  The Todo views and Lists under "Todo" are unfolded. Entering and leaving Todo set it;
	 *  clicking the Todo row or its chevron flips it; it is restored as left. None: never chosen,
	 *  so the tree follows the page (unfolded when the app opens in Todo).
	 */
	todo_open?: boolean | null,
};

/**  What the sidebar shows: the Inbox count and every List, first to last. */
export type SidebarView = {
	/**  Open Tasks with no List. */
	inbox_count: number,
	/**  Open Tasks due today, plus every Overdue one: Today's count. */
	today_count: number,
	/**  Open Tasks due before today: the Today count turns red while this is above zero. */
	overdue_count: number,
	/**  Lists in the order the sort says; dragging them is off unless this is Manual. */
	lists: ListEntry[],
	/**  How the Lists are sorted (a Preference). */
	lists_sort: ListSort,
};

/**  Where a `TaskHit`'s snippet line comes from. */
export type SnippetSource = 
/**  A line of the Task's notes. */
"notes" | 
/**  A Comment. */
"comment";

/**  A run of snippet text, either plain or a match. */
export type Span = {
	/**  The text, with whitespace collapsed to single spaces. */
	text: string,
	/**  Whether it matched the search. */
	matched: boolean,
};

/**  One thing to do. */
export type Task = {
	/**  `UUIDv7`. */
	id: string,
	/**  The List it belongs to; none means the Inbox. */
	list_id: string | null,
	/**  One line, up to 500 characters. */
	title: string,
	/**  Markdown notes. */
	notes: string,
	/**  Due date, `YYYY-MM-DD`. */
	due_date: string | null,
	/**  Due time, `HH:MM`, floating local. */
	due_time: string | null,
	/**  Repeat unit: `day`, `week`, `month` or `year`. */
	repeat_freq: string | null,
	/**  Repeat interval, 1 to 99. */
	repeat_every: number | null,
	/**  Weekday bitmask for weekly Repeats. */
	repeat_days: number | null,
	/**  `fixed` (from the Due date) or `after` (from the day it was done). */
	repeat_mode: string | null,
	/**  1 (highest) to 4 (none). */
	priority: number,
	/**  Open, done or Won't do. */
	state: TaskState,
	/**  When it was done or marked Won't do: UTC milliseconds. */
	closed_at: number | null,
	/**  For an occurrence copy, the Task it was made from. */
	repeat_of: string | null,
	/**  What the natural-language parser recognised, as JSON. */
	understood: string | null,
	/**  Text that sorts bytewise into the manual order, shared by every Task. */
	sort_key: string,
	/**  Row creation time: UTC milliseconds. */
	created_at: number,
	/**  Row update time: UTC milliseconds. */
	updated_at: number,
	/**
	 *  How many live Comments it has: counted when read, never stored (and left out of the
	 *  change-log snapshot).
	 */
	comment_count: number,
};

/**  Open Tasks of one group, with what a Task dropped (or added) there takes on. */
export type TaskGroup = {
	/**  Which group. */
	key: GroupKey,
	/**
	 *  The properties a Task dropped here adopts, in `todo_task_reorder`'s terms: a day sets the
	 *  date, a Priority sets the Priority, a List moves it. Overdue adopts nothing: dragging
	 *  among Overdue Tasks only reorders.
	 */
	adopt: GroupKey[],
	/**  Its Tasks, sorted. */
	tasks: Task[],
};

/**  One Task found by a search. */
export type TaskHit = {
	/**  The Task, as every list shows it. */
	task: Task,
	/**  Its title cut into plain and matched runs, for highlighting. */
	title: Span[],
	/**
	 *  The note or Comment line that matched, with the matches marked; empty when only the title
	 *  matched.
	 */
	snippet: Span[],
	/**  Where `snippet` came from. */
	snippet_source: SnippetSource | null,
};

/**
 *  The outcome of a search. Within each group open Tasks come first (manual order), then Done and
 *  Won't do ones (latest closed first); the UI splits on `task.state`.
 */
export type TaskSearchResults = {
	/**  Tasks that match every word and phrase. */
	exact: TaskHit[],
	/**  Tasks that match only when a word is allowed a typo; never also in `exact`. */
	similar: TaskHit[],
	/**  Whether `exact` was cut short at the limit. */
	truncated: boolean,
	/**  Whether `similar` was cut short at the limit. */
	similar_truncated: boolean,
};

/**  How the Tasks inside one group are ordered. */
export type TaskSort = 
/**  The drag order. */
"manual" | 
/**  Earliest Due date and time first; undated last. */
"due" | 
/**  Most urgent Priority first. */
"priority" | 
/**  Title, A to Z, ignoring case and accents. */
"title" | 
/**  Newest first. */
"added";

/**  Where a Task stands. A Task is open until it is done or marked Won't do. */
export type TaskState = 
/**  Still to do. */
"open" | 
/**  Completed; `closed_at` says when. */
"done" | 
/**  Decided against; `closed_at` says when. */
"wont";

/**  A stretch of the text, in UTF-16 code units. */
export type TextRange = {
	/**  First unit. */
	start: number,
	/**  One past the last unit. */
	end: number,
};

/**  The Entry written last on the day. */
export type TodayLatest = {
	/**  `UUIDv7`. */
	id: string,
	/**  When it was written: UTC milliseconds. */
	written_at: number,
	/**  UTC offset in minutes where it was written. */
	written_offset_min: number,
	/**  IANA zone where it was written. */
	written_tz: string,
	/**  Its text as plain reading text (no Markdown), cut at about 140 characters. */
	snippet: string,
};

/**  What the Home card shows about one day. */
export type TodaySummary = {
	/**  Live Entries on the day's Page. */
	count: number,
	/**  The Entry written last, `None` on an empty day. */
	latest: TodayLatest | null,
};

/**  Today: what is late, what is due, and what is already done. */
export type TodayView = {
	/**  How today's Tasks are grouped (a Preference). */
	group_by: GroupBy,
	/**
	 *  Overdue on top (open Tasks due before today, oldest date first), then today's Tasks in
	 *  groups: timed ones by time, then the rest in manual order, a more urgent Priority first
	 *  inside one time block. A timed Task whose time has passed stays here. Priority groups
	 *  appear only when some Task due today has a Priority.
	 */
	groups: TaskGroup[],
	/**  Tasks done today, earliest first. Won't do is not counted. */
	done: Task[],
	/**  Overdue, due and done today together: the "of M" in "N of M done". */
	total: number,
};

/**  What the badge and the Home card show, in one read. */
export type TodoCounts = {
	/**  Open Tasks due today. */
	due_today: number,
	/**  Open Tasks due before today: the badge turns red while this is above zero. */
	overdue: number,
	/**  Up to five of the open Tasks due today, in Today's order (timed ones first). */
	card: Task[],
	/**  The soonest open Task due after today, for "Nothing due today · next: ...". */
	next: Task | null,
	/**  Whether any Task exists, done or not: false only on a first run. */
	any_tasks: boolean,
};

/**  A flat group of Tasks. Tasks with no List are in the Inbox, which is not a List. */
export type TodoList = {
	/**  `UUIDv7`. */
	id: string,
	/**  Unique among Lists once case and accents are ignored; up to 60 characters. */
	name: string,
	/**  One emoji shown beside the name; none shows a neutral list icon. */
	emoji: string | null,
	/**  Text that sorts bytewise into the List order. */
	sort_key: string,
	/**  How its page sorts the Tasks inside each group. */
	task_sort: TaskSort,
	/**  How its page groups its Tasks: None, Priority or Due date. */
	group_by: GroupBy,
	/**  Row creation time: UTC milliseconds. */
	created_at: number,
	/**  Row update time: UTC milliseconds. */
	updated_at: number,
};

/**  Upcoming: Overdue on top, then the Tasks from tomorrow on in groups. */
export type UpcomingView = {
	/**  How the coming Tasks are grouped (a Preference): by day unless changed. */
	group_by: GroupBy,
	/**
	 *  Overdue first, then the groups. By day, only days that have Tasks, earliest first; inside
	 *  any group Tasks run by date, timed ones by time, then the manual order.
	 */
	groups: TaskGroup[],
};

/**  Last known window geometry. */
export type WindowState = {
	/**  Inner width in logical pixels. */
	w?: number,
	/**  Inner height in logical pixels. */
	h?: number,
	/**  Left edge, if ever saved. */
	x?: number | null,
	/**  Top edge, if ever saved. */
	y?: number | null,
	/**  Whether the window was maximized. */
	maximized?: boolean,
};

/* Tauri Specta runtime */
async function typedError<T, E>(result: Promise<T>): Promise<{ status: "ok"; data: T } | { status: "error"; error: E }> {
    try {
        return { status: "ok", data: await result };
    } catch (e) {
        if (e instanceof Error) throw e;
        return { status: "error", error: e as any };
    }
}

type EventEmit<T> = [T] extends [null] ? () => Promise<void> : (payload: T) => Promise<void>;

function makeEvent<T>(name: string, serialize?: (payload: T) => unknown, deserialize?: (payload: any) => T) {
    const mapEvent = (cb: __TAURI_EVENT.EventCallback<T>) => (event: __TAURI_EVENT.Event<any>) => cb({ ...event, payload: deserialize ? deserialize(event.payload) : event.payload });
    const mapPayload = (payload: T) => serialize ? serialize(payload) : payload;

    const base = {
        listen: (cb: __TAURI_EVENT.EventCallback<T>) => __TAURI_EVENT.listen(name, mapEvent(cb)),
        once: (cb: __TAURI_EVENT.EventCallback<T>) => __TAURI_EVENT.once(name, mapEvent(cb)),
        emit: ((payload: T) => __TAURI_EVENT.emit(name, mapPayload(payload)) as unknown) as EventEmit<T>
    };

    const fn = (target: import("@tauri-apps/api/webview").Webview | import("@tauri-apps/api/window").Window) => ({
        listen: (cb: __TAURI_EVENT.EventCallback<T>) => target.listen(name, mapEvent(cb)),
        once: (cb: __TAURI_EVENT.EventCallback<T>) => target.once(name, mapEvent(cb)),
        emit: ((payload: T) => target.emit(name, mapPayload(payload)) as unknown) as EventEmit<T>
    });

    return Object.assign(fn, base);
}

